/* tpg_fpga — NTSC test pattern generator for the FreeWili 2, as a display app,
 * with the video generated by the iCE40 FPGA.
 *
 * Same signal, patterns and header pins as the OG TPG (apps/tpg) and the
 * ZoomIO app (fw2/apps/tpg_zio); the gateware is fpga/tpg (wilifpga), built
 * and embedded at build time (gen_fwfpga_header.py -> tpg_fwfpga.h). Needs
 * FW2 firmware v11 or newer on MAIN (Hardware > FPGA, h\f).
 *
 *   B2 B1 B0   GPIO  8  9 10   header  9  5  7
 *   G2 G1 G0   GPIO 11 12 13   header 11 12  1
 *   R2 R1 R0   GPIO 14 15 26   header 15 13 14
 *   CSYNC      GPIO 27         header  3        (active low)
 *
 * At start the app selects the 3.3 V VIO rail, holds power zone 6 (FPGA),
 * makes sure /fpga/tpg.fwfpga on the SD card is this build's (same size and
 * the same 256-byte header, which carries the bitstream's SHA-256), rewrites
 * it if not, and loads it with h\f\l. MAIN sets every header direction from
 * the file, so no IO-direction commands are needed. If the design is already
 * running (Default FPGA, or an earlier run) nothing is reloaded and the
 * pattern it shows is kept.
 *
 * Switching pattern is one register write (0x10, h\f\w); the FPGA changes at
 * the next field. Besides the nine shared patterns the FPGA has a tenth,
 * FOCUS (H), and a text overlay naming the pattern and the timing (0x13
 * bit 0, on after a load). Every 2 s the app reads 0x10 and 0x13 back and
 * reloads / rewrites them if they differ, which covers MAIN rebooting or
 * zone 6 dropping.
 *
 * GREEN next pattern, YELLOW previous, BLUE text overlay on / off, RED stock
 * FPGA (outputs released) / back to TPG. HOLD HOME 5 S leaves the app but not
 * the pattern: the FPGA keeps generating it until it is restored (h\f\t),
 * reloaded or powered off. */
#include "fw2.h"
#include "platform/diag.h"
#include "pico/stdlib.h"
#include "onewili.h"
#include "onewili_fwgui.h"
#include "onewili_sd.h"
#include "input/app_recovery_onewili.h"
#include "common/tpg_patterns.h"
#include "tpg_fwfpga.h"
#include <stdarg.h>
#include <stdio.h>
#include <string.h>

#define FPGA_DIR  "/fpga"
#define FPGA_FILE FPGA_DIR "/" TPG_FWFPGA_NAME ".fwfpga"
#define REG_PATTERN 0x10
#define REG_CONTROL 0x13   /* bit 0: text overlay */

/* The nine shared patterns (common/tpg_patterns.h) plus the FPGA-only focus
 * screen, which the design numbers 9. */
#define PATTERN_FOCUS ((unsigned)TPG_PATTERN_COUNT)
#define PATTERN_COUNT (TPG_PATTERN_COUNT + 1u)

/* ~37 KB of link buffers — far too big for the 2 KB stack. */
static ow_device dev;
static char reply[OW_RESP_MAX];

static unsigned pattern = TPG_PATTERN_COLOR_BARS;
static bool overlay = true;   /* the FPGA's text overlay (CONTROL bit 0) */
static bool active;           /* the TPG design is loaded and showing `pattern` */

static const char *pattern_name(unsigned p) {
    return p == PATTERN_FOCUS ? "FOCUS (H)" : tpg_pattern_name((tpg_pattern_id_t)p);
}

static inline uint16_t be16(uint16_t c) {
    return (uint16_t)((c >> 8) | (c << 8));
}

#define C_BLACK be16(0x0000)
#define C_WHITE be16(0xFFFF)
#define C_GREEN be16(0x07E0)
#define C_RED   be16(0xF800)
#define C_GREY  be16(0x8410)
#define C_BLUE  be16(0x0010)

/* Status rows at scale 2 (16 px glyphs, 29 columns inside the margins),
 * below the pattern name. */
enum { ROW_STATE, ROW_REPLY, ROW_REPLY2, ROW_LINK, ROW_POWER, ROW_COUNT };
#define ROW_Y(r) (120 + (r) * 26)
#define NAME_Y   48

static void line(int row, uint16_t fg, const char *fmt, ...) {
    char s[30];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(s, sizeof s, fmt, ap);
    va_end(ap);
    st7796_fill_rect(8, ROW_Y(row), 464, 16, C_BLACK);
    st7796_draw_text(8, ROW_Y(row), 2, fg, C_BLACK, s);
}

/* The pattern name at scale 4 (24 x 32 px glyphs: 19 columns) with its
 * position in the cycle and the overlay state. */
static void show_pattern(void) {
    char n[24];
    st7796_fill_rect(8, NAME_Y, 464, 64, C_BLACK);
    st7796_draw_text(8, NAME_Y, 4, C_WHITE, C_BLACK, pattern_name(pattern));
    snprintf(n, sizeof n, "%u/%u   TEXT %s", pattern + 1u, PATTERN_COUNT, overlay ? "ON" : "OFF");
    st7796_draw_text(8, NAME_Y + 40, 2, C_GREY, C_BLACK, n);
}

/* Bottom-row labels, one fifth per button (wilibsp AGENTS.md), the grey slot
 * left empty because that button does nothing here. */
static void button_bar(void) {
    const int w = (ST7796_W - 12) / 5, h = 34, y = ST7796_H - h;
    st7796_fill_rect(1 * 96, y, w, h, 0x06FF);   /* yellow, wire order */
    st7796_draw_text(1 * 96 + 14, y + 9, 2, C_BLACK, 0x06FF, "PREV");
    st7796_fill_rect(2 * 96, y, w, h, 0x0012);   /* green, wire order */
    st7796_draw_text(2 * 96 + 14, y + 9, 2, C_WHITE, 0x0012, "NEXT");
    st7796_fill_rect(3 * 96, y, w, h, C_BLUE);
    st7796_draw_text(3 * 96 + 14, y + 9, 2, C_WHITE, C_BLUE, "TEXT");
    st7796_fill_rect(4 * 96, y, w, h, 0x0780);   /* red, wire order */
    st7796_draw_text(4 * 96 + 8, y + 9, 2, C_WHITE, 0x0780, active ? "STOP" : "RUN");
}

/* MAIN's reply body across two rows (it is free text on failure). */
static void show_reply(const char *text, bool ok) {
    char a[30] = "", b[30] = "";
    if (ok) {
        line(ROW_REPLY, C_BLACK, "");
        line(ROW_REPLY2, C_BLACK, "");
        return;
    }
    snprintf(a, sizeof a, "%s", text[0] ? text : "(ERR, NO TEXT)");
    if (strlen(text) > 29) snprintf(b, sizeof b, "%s", text + 29);
    line(ROW_REPLY, C_RED, "%s", a);
    line(ROW_REPLY2, C_RED, "%s", b);
}

/* Send one menu command through the raw path; MAIN's reply body is left in
 * `reply`. The generated bindings have no FPGA commands yet (v11 added them
 * as OneWili 694-702) and report only OK / FAILED anyway, while a failure's
 * text (EPOWERZONE, header:no-file, ...) is what the user needs to see. With
 * quiet set, a failure is logged but not shown. */
static bool call(const char *label, const char *cmd, bool quiet) {
    int ok = 0;
    reply[0] = '\0';
    ow_raw_stash_clear();
    if (ow_raw_send(&dev, cmd) < 0) {
        DIAG("tpg_fpga: %s send failed\n", label);
        if (!quiet) show_reply("SEND FAILED", false);
        return false;
    }
    ow_status s = ow_raw_next_response(&dev, reply, sizeof reply, &ok, 10000);
    if (s != OW_OK) {
        DIAG("tpg_fpga: %s no response, status %d\n", label, (int)s);
        reply[0] = '\0';
        if (!quiet) show_reply(s == OW_ERR_TIMEOUT ? "NO REPLY (TIMEOUT)" : "NO REPLY (LINK ERROR)", false);
        return false;
    }
    DIAG("tpg_fpga: %s ok=%d reply '%s'\n", label, ok, reply);
    if (!quiet) show_reply(reply, ok != 0);
    return ok != 0;
}

/* MAIN gates the FPGA and header on zone 6 using the zone state DISPLAY
 * reports (event 48). The stock DISPLAY firmware sends that; a RAM app that
 * replaced it must too, or MAIN refuses with EPOWERZONE 6 FPGA. */
static void report_zones(void) {
    uint32_t rails;
    if (picpwr_rails(&rails)) ow_fwgui_send_power_zones(rails);
}

/* h\f\s: `source armed cdone id version caps clock_hz profile name load_ms
 * error [contention]`. True when the TPG design of this build is armed. */
static bool tpg_running(bool quiet) {
    char source[16];
    int armed = 0, cdone = 0;
    unsigned id = 0, version = 0;
    if (!call("STATUS", "h\\f\\s", quiet)) return false;
    if (sscanf(reply, "%15s %d %d %u %u", source, &armed, &cdone, &id, &version) != 5) return false;
    return armed == 1 && id == TPG_FWFPGA_DESIGN_ID && version == TPG_FWFPGA_VERSION;
}

/* h\f\r <addr> 1 -> "NN" (hex). */
static bool read_reg(const char *label, unsigned addr, unsigned *value) {
    char cmd[24];
    snprintf(cmd, sizeof cmd, "h\\f\\r %02X 1", addr);
    return call(label, cmd, true) && sscanf(reply, "%x", value) == 1;
}

static bool write_reg(const char *label, unsigned addr, unsigned value) {
    char cmd[24];
    snprintf(cmd, sizeof cmd, "h\\f\\w %02X %02X", addr, value);
    return call(label, cmd, false);
}

static bool write_pattern(void) {
    return write_reg("WRITE PATTERN", REG_PATTERN, pattern);
}

static bool write_control(void) {
    return write_reg("WRITE CONTROL", REG_CONTROL, overlay ? 1u : 0u);
}

/* Same size and the same header (it carries the bitstream's CRC-32 and
 * SHA-256) as the embedded file. */
static bool sd_file_current(void) {
    bool is_dir = false;
    uint32_t size = 0;
    if (ow_sd_stat(&dev, FPGA_FILE, &is_dir, &size) != OW_OK || is_dir || size != TPG_FWFPGA_LEN)
        return false;
    static uint8_t head[TPG_FWFPGA_HEADER_LEN];
    ow_sd_file f;
    size_t got = 0;
    if (ow_sd_open(&dev, &f, FPGA_FILE, OW_SD_READ) != OW_OK) return false;
    const ow_status s = ow_sd_read(&f, head, sizeof head, &got);
    (void)ow_sd_close(&f);
    return s == OW_OK && got == sizeof head && memcmp(head, TPG_FWFPGA, sizeof head) == 0;
}

/* The embedded file in single-chunk pieces. ow_sd_put_mem sends a
 * multi-chunk file without per-chunk acknowledgement, and over the display
 * link a chunk can be dropped (OW_ERR_PROTOCOL: the server saw a gap). Each
 * piece of at most SDFS_MAX_PAYLOAD bytes is confirmed on its own; any
 * failure restarts the file, since its first piece truncates. */
static bool write_sd_file(void) {
    (void)ow_sd_mkdir(&dev, FPGA_DIR);   /* exists after the first run */
    for (int attempt = 0; attempt < 3; attempt++) {
        size_t off = 0;
        ow_status s = OW_OK;
        do {
            const size_t left = TPG_FWFPGA_LEN - off;
            const size_t n = left < SDFS_MAX_PAYLOAD ? left : SDFS_MAX_PAYLOAD;
            if ((off & 0x3FFF) == 0)
                line(ROW_STATE, C_WHITE, "WRITING GATEWARE %u%%", (unsigned)(off * 100u / TPG_FWFPGA_LEN));
            s = ow_sd_put_mem(&dev, FPGA_FILE, TPG_FWFPGA + off, n, off != 0);
            off += n;
        } while (s == OW_OK && off < TPG_FWFPGA_LEN);
        if (s == OW_OK) return sd_file_current();
        DIAG("tpg_fpga: put attempt %d failed at %u: status %d (sdfs %d)\n",
             attempt + 1, (unsigned)off, (int)s, (int)ow_sd_last_error());
    }
    line(ROW_STATE, C_RED, "GATEWARE WRITE FAILED");
    return false;
}

/* h\f\l -> `id version cdone load_ms` on success. */
static bool load_design(void) {
    line(ROW_STATE, C_WHITE, "LOADING FPGA...");
    report_zones();
    if (!call("LOAD", "h\\f\\l \"" FPGA_FILE "\"", false)) return false;
    unsigned id = 0, version = 0;
    int cdone = 0;
    return sscanf(reply, "%u %u %d", &id, &version, &cdone) == 3 && id == TPG_FWFPGA_DESIGN_ID &&
           version == TPG_FWFPGA_VERSION && cdone == 1;
}

/* Load the TPG design unless it is already running, writing the SD file
 * first when it is missing or from another build. */
static bool ensure_design(void) {
    if (tpg_running(true)) return true;
    if (!sd_file_current() && !write_sd_file()) return false;
    return load_design();
}

static void start(void) {
    show_pattern();
    line(ROW_STATE, C_WHITE, "STARTING...");
    active = ensure_design() && write_pattern() && write_control();
    line(ROW_STATE, active ? C_GREEN : C_RED, active ? "RUNNING (FPGA)" : "START FAILED");
    button_bar();
}

static void select_pattern(unsigned p) {
    pattern = p;
    show_pattern();
    if (!active) return;   /* shown when RUN is pressed */
    if (!write_pattern()) start();   /* design gone? reload it */
}

static void toggle_overlay(void) {
    overlay = !overlay;
    show_pattern();
    if (!active) return;   /* applied when RUN is pressed */
    if (!write_control()) start();
}

static void stop(void) {
    active = false;
    const bool ok = call("RESTORE STOCK", "h\\f\\t", false);
    line(ROW_STATE, ok ? C_GREY : C_RED, ok ? "STOPPED, STOCK FPGA" : "RESTORE FAILED");
    button_bar();
}

/* Hold the FPGA rail and wait (bounded) until the coprocessor reports it. */
static bool fpga_zone_up(void) {
    const uint32_t bit = picpwr_zone_bit(PICPWR_ZONE_FPGA);
    picpwr_keep_awake(bit);
    for (uint32_t waited = 0; waited < 5000; waited += 10) {
        uint32_t rails = 0;
        if (picpwr_rails(&rails) && (rails & bit)) return true;
        fw2_app_recovery_sleep_ms(10);
    }
    return false;
}

int main(void) {
    board_init();   /* must precede ow_open_fwgui: uart_init reads clk_peri */
    fw2_app_recovery_init();
    st7796_init();
    fw2_app_about_use_lcd();
    agentio_init();   /* before the first clear: it owns the capture shadow */
    st7796_fill_screen(C_BLACK);
    st7796_draw_text(8, 8, 2, C_WHITE, C_BLACK, "TPG  NTSC 240P  FPGA");
    show_pattern();
    button_bar();
    board_backlight_set(1);
    ioexp_vref(VREF_3V3);   /* required: no VIO rail => the header pins cannot drive */

    line(ROW_POWER, C_WHITE, "FPGA ZONE 6...");
    const bool fpga = fpga_zone_up();
    picpwr_release_unused();
    DIAG("tpg_fpga: FPGA zone %s\n", fpga ? "up" : "NOT reported up");
    line(ROW_POWER, fpga ? C_GREY : C_RED, "FPGA ZONE 6 %s", fpga ? "ON" : "NOT ON");

    line(ROW_LINK, C_WHITE, "CONNECTING TO MAIN...");
    while (fw2_app_recovery_open_onewili(&dev) != OW_OK) {
        fw2_app_recovery_task();
        DIAG("tpg_fpga: FwGUI link open failed (is the main CPU running stock fw?), retry in 1 s\n");
        line(ROW_LINK, C_RED, "MAIN LINK FAILED, RETRY");
        fw2_app_recovery_sleep_ms(1000);
    }
    if (fw2_app_recovery_wrap_sd() != OW_OK) {
        DIAG("tpg_fpga: recovery-aware SD transport setup failed\n");
        line(ROW_LINK, C_RED, "SD TRANSPORT SETUP FAILED");
    } else {
        line(ROW_LINK, C_GREY, "MAIN LINK UP");
    }
    report_zones();
    fw2_app_recovery_sleep_ms(100);   /* fire-and-forget: let MAIN apply it */

    /* Already running (Default FPGA or an earlier run): keep its pattern and
     * overlay state. */
    unsigned shown = 0, ctrl = 0;
    if (tpg_running(true)) {
        if (read_reg("READ PATTERN", REG_PATTERN, &shown) && shown < PATTERN_COUNT) pattern = shown;
        if (read_reg("READ CONTROL", REG_CONTROL, &ctrl)) overlay = (ctrl & 1u) != 0;
    }
    start();

    uint64_t next_report_us = 0, next_check_us = time_us_64() + 2000000u;
    for (;;) {
        fw2_app_recovery_task();
        agentio_task();

        uartkbd_event_t ev;
        while (uartkbd_next_event(&ev)) {
            if (!ev.pressed) continue;
            if (ev.btn == UARTKBD_BTN_GREEN) {
                select_pattern((pattern + 1u) % PATTERN_COUNT);
            } else if (ev.btn == UARTKBD_BTN_YELLOW) {
                select_pattern((pattern + PATTERN_COUNT - 1u) % PATTERN_COUNT);
            } else if (ev.btn == UARTKBD_BTN_BLUE) {
                toggle_overlay();
            } else if (ev.btn == UARTKBD_BTN_RED) {
                if (active) stop();
                else start();
            }
        }

        const uint64_t now = time_us_64();
        if (now >= next_report_us) {
            report_zones();   /* MAIN may have rebooted: keep it informed */
            next_report_us = now + 1000000u;
        }
        /* MAIN rebooted or zone 6 dropped: the stock image (or reset
         * registers) is back. Reload / rewrite. */
        if (active && now >= next_check_us) {
            unsigned value = 0, ctrl = 0;
            if (!tpg_running(true) || !read_reg("READ PATTERN", REG_PATTERN, &value) || value != pattern ||
                !read_reg("READ CONTROL", REG_CONTROL, &ctrl) || (ctrl & 1u) != (overlay ? 1u : 0u)) {
                DIAG("tpg_fpga: design or pattern lost, restarting\n");
                start();
            }
            next_check_us = time_us_64() + 2000000u;
        }
        fw2_app_recovery_sleep_ms(10);
    }
}
